"""逐题编写24道复合训练，不改变国考原题，不用循环换数扩题。"""
import json, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent
Q=[]
def add(n, level, h, s, options, answer, hint, solution, trap, check):
    Q.append(dict(uid=f'challenge:{n:03}',sourceType='mock',sourceLabel='原创模拟·复合24',generator='AI逐题编写（非真题）',level=level,h=h,t='复合模型',s=s,o=list(map(str,options)),a=answer,hint=hint,e=solution,tr=trap,template=f'challenge-{n:03}',timeLimit=75 if level=='深化' else 100,check=check))
add(1,'深化','比例调配','甲、乙两个服务站共有180名工作人员，人数之比为5∶4。现从甲站调若干人至乙站，调动后甲、乙人数之比为9∶11。应调动多少人？',[9,18,19,20],2,'人数总量不变，比较甲站前后所占份额。','调动前甲占5/9，调动后占9/20；调出180×(5/9−9/20)=19人。不必分别设两站人数再列两式；常规解为100−81，也只需两步。','比例的分母是两站总份数，不能拿5与9直接相减。',{'kind':'transfer','total':180,'before':[5,4],'after':[9,11]} )
add(2,'综合','资源约束与分段费用','制作一套应急包需要2个A组件和3个B组件。库存分别为180个和210个。补购A每个4元、B每个6元，预算300元，组件只能整件购买。最多可制作多少套？',[85,86,87,90],1,'每个选项都是一个生产目标，分别算缺口费用。','做86套需A172个、B258个，只缺B48个，花288元；做87套缺B51个，花306元，超预算。套数增加只会让采购费用不减，86可行、87不可行即锁定上界。','不能把库存总件数相加平均分；也不用先解完整整数规划。',{'kind':'resource','stock':[180,210],'need':[2,3],'price':[4,6],'budget':300})
add(3,'综合','整日产能与瓶颈','一套设备需要2个A模块和3个B模块。甲车间每天可生产6个A或3个B，乙车间每天可生产2个A或6个B。两车间各生产6天，每天只能选一种模块且不能拆分半天，余料可保留。最多配成多少套？',[12,13,14,15],1,'先让甲多做A、乙多做B，再围绕瓶颈检查一日切换。','令甲做A的天数x、乙做A的天数y，则A=6x+2y，B=54−3x−6y。13套可用x=5、y=0：A30、B39。若要14套，则3x+y≥14且x+2y≤4，两式在非负整数域无解（x+2y≤4使3x+y≤12）。所以上界13。','本例连续放松上界为13.5套，向下取整是13，但仍须给出达到13套的整日方案；不能声称整日约束在这组参数中必然降低整套数。',{'kind':'production','days':6,'rates':[[6,3],[2,6]],'need':[2,3]})
add(4,'深化','往返与停留','甲、乙同时从P地向180千米外的Q地出发，速度分别为60、40千米/时。甲到Q后停留半小时，再沿原路返回，其余时间两人均匀速且不停留，途中与乙相遇。相遇点距Q多少千米？',[18,24,30,36],1,'把停留造成的少走路程扣掉，合计路程仍是两个全程。','从出发到相遇共t小时，甲行驶t−0.5小时，两人路程和360千米：60(t−0.5)+40t=360，得t=3.9。乙距Q为180−40×3.9=24千米。检查：甲3小时到Q，3.5小时返程，相遇确在返程后。','把停留时间忘掉会算成36千米；须核对相遇发生在哪个阶段。',{'kind':'return','length':180,'fast':60,'slow':40,'rest':'1/2'})
add(5,'深化','环形相对速度','甲乙从环形跑道同一点出发，同向跑时甲每150秒追上乙一次，反向跑时每30秒相遇一次。两人分别在两种跑法中保持各自的速度不变。甲速度是乙的多少倍？',['3/2','2','5/2','3'],0,'一圈路程相同，速度和与速度差反比于相遇间隔。','设一圈为300单位，速度差=2，速度和=10，甲6、乙4，速度比3∶2。无需知道跑道实际长度。','150∶30是速度和与差的比，不是甲乙速度比。',{'kind':'ring','same':150,'opposite':30})
add(6,'深化','年龄总和与严格边界','甲乙丙丁今年年龄之和为144岁。甲比乙大6岁，丙的年龄是乙的2倍，丁的年龄是甲的一半。从今年起经过多少个整年，四人年龄之和首次超过180岁？',[8,9,10,12],2,'问题只问总和越界，个人年龄关系可以不算。','四人每过一年总和增加4岁，只需144+4t>180，即t>9，最早10个整年。题中的个人年龄关系用于核实背景，不是所求必需信息。','9年后恰为180，不是超过；不要被三个年龄关系引去解四个人的年龄。',{'kind':'age','sum':144,'people':4,'threshold':180})
add(7,'综合','平均数与名次极值','10名考生平均80分，成绩均为0至100之间的整数且互不相同。其中一人87分。此人的名次最低可能为第几名（按成绩从高到低）？',[7,8,9,10],1,'要让87分尽量靠后，先把更高分者按88、89……取最小值。','若8人在前，其最小总分88+…+95=732，加87已819>800，不可能。7人在前可取88至94，合637；其余两人37、39，加87总分800，全部不同。因此最差第8名。','极值不能只给上界；必须给出可行构造，确保名次能达到。',{'kind':'rank','n':10,'total':800,'fixed':87})
add(8,'综合','互异分组与双重边界','65人分为5组，每组至少8人，各组人数互不相同，最大组人数不超过最小组的2倍。最大组最多有多少人？',[17,18,19,20],2,'设最小组s；其余三个小组至少s+1、s+2、s+3。','最大组L同时满足L≤2s和L≤65−(4s+6)=59−4s。s≤9时L≤18；s≥10时L≤19。取10、11、12、13、19合65，满足全部条件，故最大19。','单独用至少8人会高估最大组，单独用两倍关系又漏总量；要交叉两个上界。',{'kind':'groups','total':65,'groups':5,'minimum':8,'ratio':2})
add(9,'深化','月历逆推','某个有31天的月份恰好有5个星期一、5个星期二和5个星期三。紧接着的下个月有30天。下个月的第三个星期五是几号？',[15,16,17,18],1,'31天是4周加3天，多出的三个星期连续出现。','这31天多出的周一、周二、周三说明本月1日为周一，31日为周三。下月1日周四，第一个周五2日，第三个周五为16日。','月末到次月1日还要前进一天；不要把周三当作次月起点。',{'kind':'calendar','days':31,'start':0,'nextDays':30,'weekday':4,'occurrence':3})
add(10,'综合','整除与条件排列概率','将数字1、2、3、4、5、6各使用一次，等可能地组成一个六位数。已知这个六位数能被4整除，数字1与2在该数中相邻的概率是多少？',['1/4','1/3','3/8','1/2'],2,'先用末两位筛出条件样本，再按1和2是否出现在末两位分类；不能直接套无条件相邻概率。','末两位只能12、16、24、32、36、52、56、64，共8种，每种前四位有4!=24种，条件样本192种。相邻事件分类：尾12已经相邻，有24种；尾16或24时，另一数字只能紧贴在第四位，各3!=6种，尾32或52时无法相邻；尾36、56、64都不含1、2，把前四位的1、2捆绑，各2×3!=12种。因此有24+2×6+3×12=72种，概率72/192=3/8。','无条件下捆绑可得2/6=1/3，但已知能被4整除后，末位分布已变，不能沿用无条件结果。先缩小样本空间，再检查相邻能否跨过前四位与末两位的边界。',{'kind':'digit_probability','digits':[1,2,3,4,5,6],'divisor':4,'adjacent':[1,2]})
add(11,'综合','前缀约束与终态','某竞赛有7道次序固定的判断题，起始0分，答对加1分、答错扣1分。要求答完每一题后的分数都大于0，且最终得3分。共有多少种对错序列？',[5,9,14,21],1,'最终3分先锁定5对2错，第一题必须对，再限制两次错误位置。','两道错题位置i<j。第一题不能错，第二题错会归零，所以i≥3；当第二次错误发生时得分为j−4，必须正，故j≥5。j=5、6、7分别可取i为3到j−1，计2+3+4=9。其余步骤只加分，只需检查两次下降后的最低点，即覆盖所有前缀。','只算C(7,2)漏掉过程要求；大于0与不低于0不是同一个边界。',{'kind':'prefix','n':7,'end':3,'strict':True})
add(12,'综合','独立概率与条件样本','甲乙独立完成一次设备检测，通过概率分别为0.8和0.75。已知至少一人通过，恰有一人通过的概率是多少？',['7/20','7/19','3/5','13/19'],1,'条件概率先缩小样本：分母是至少一人通过。','恰一人=0.8×0.25+0.2×0.75=0.35；至少一人=1−0.2×0.25=0.95。条件概率0.35/0.95=7/19。','7/20只算无条件概率；已知事件必须体现在分母。',{'kind':'conditional','p':'4/5','q':'3/4'})
add(13,'深化','不放回与条件概率','袋中有3个红球、4个蓝球，球除颜色外相同。随机不放回取2球，已知至少有1个红球，2球均为红球的概率是多少？',['1/7','1/5','2/7','3/7'],1,'先排掉全蓝组合，再在剩余组合里数全红。','全部C(7,2)=21，去掉全蓝C(4,2)=6，条件样本15种；全红C(3,2)=3，概率3/15=1/5。无序组合等可能，可直接约分。','至少一红不等于恰一红；不放回不能把两次概率视为独立。',{'kind':'balls','red':3,'blue':4,'draw':2})
add(14,'深化','面积差与周长','长方形场地长宽比3∶2，外围修建宽2米的道路，外边界仍为长方形，四角均为2米×2米的正方形。道路面积116平方米。原场地周长多少米？',[40,46,50,58],2,'面积差展开后，原面积项抵消，只剩周长贡献和四角。','长宽设3x、2x，道路面积(3x+4)(2x+4)−6x²=20x+16=116，x=5，周长2×5x=50米。也可用道路面积=道路宽×原周长+4×宽²直接反推。','四角16平方米不能漏掉；外部长宽均增加4，不是2。',{'kind':'border','width':2,'area':116})
add(15,'综合','相似体积与分段注水','容器竖直放置，下部是内高12厘米、尖端向下的圆锥，上部是同内底面半径的圆柱。水深从尖端量起且容器不漏水。以恒定体积流量从空容器注水，2分钟时水深6厘米。容器足够高，水深18厘米时共注水多少分钟？',[24,32,40,48],2,'圆锥内液体相似缩放，水深一半对应体积的1/8。','圆锥注满需2×8=16分钟。水深18时圆柱段高6，体积为底面积×6，是完整圆锥（底面积×4）的1.5倍，又需24分钟，总40分钟。','恒定流量不代表液面匀速；锥体阶段按高度立方，柱体阶段才按高度一次。',{'kind':'vessel','coneHeight':12,'initialHeight':6,'initialTime':2,'target':18})
add(16,'深化','切割与新增表面积','一个长12厘米、宽8厘米、高6厘米的长方体，沿长度方向等分成3块（切面均为8×6的长方形），忽略切割损耗，随后三块完全分开。三块表面积之和是多少平方厘米？',[528,576,624,720],2,'每切一刀增加两个截面；三块只需两刀。','原表面积2×(12×8+12×6+8×6)=432；新增2刀×2面×48=192，共624。无需分别计算每块6个面。','三块不是三刀；只增加切面，原外表面没有消失。',{'kind':'cut','sides':[12,8,6],'pieces':3})
add(17,'深化','分段等差与消元','某站点一年12个月业务量按等差数列递增，前三个月合计240件，接下来三个月合计330件。全年业务量合计多少件？',[1320,1440,1500,1560],2,'两个三月块相差3个月位移，块总差是9倍公差。','330−240=9d，d=10。前三月平均即第2月80，首月70；12个月和=12×(70+180)/2=1500。用季度块也可：240、330、420、510合1500。','季度总增量90不是月公差；求全年无需逐月写表。',{'kind':'arithmetic','firstBlock':240,'nextBlock':330,'block':3,'months':12})
add(18,'深化','利润与离散优化','某商品单件成本80元，售价120元时每天销售100件。每降价10元，每天销量增加50件；只允许按10元的整数倍降价且售价不低于成本。不计其他成本，日利润最高时售价多少元？',[90,100,110,120],2,'利润是两个变化量的乘积，代入少量合法价格即可。','降价0、10、20、30、40元时，利润分别40×100=4000、30×150=4500、20×200=4000、10×250=2500、0。最高为110元。此题只有5种状态，不值得展开求连续极值。','销量最高不等于利润最高。本例连续最优价也恰为110元，不用于证明离散与连续最优必有差别。',{'kind':'profit','cost':80,'price':120,'sales':100,'step':10,'growth':50})
add(19,'深化','件数差量与阶梯运费','35件包裹，每件重1千克或4千克，总重83千克。每件包裹前2千克以内收费12元，超出部分每千克加3元。总运费多少元？',[498,510,516,528],2,'先假设全是轻件，重量差求重件数；费用同样用差量。','全为1千克共35千克，重件数(83−35)/3=16。轻件12元，重件18元，全部按基础费再加重件增量：35×12+16×6=516。','4千克不是另加4×3；每件各自计首重，不能对总重一次计费。',{'kind':'shipping','count':35,'weight':83,'light':1,'heavy':4,'base':12,'included':2,'extra':3})
add(20,'综合','浓度与蒸发守恒','浓度均指溶质质量分数，按理想混合模型忽略析出与其他损耗。用20%和40%的溶液配成30千克混合液，再蒸发6千克纯水后，浓度变为40%。应取原40%溶液多少千克？',[12,15,18,24],2,'先从蒸发后的总质量反推溶质质量，再回到混合前。','最终24千克、溶质9.6千克；混合前溶质质量相同。设原40%溶液x千克，0.4x+0.2(30−x)=9.6，x=18。或先求混合浓度32%，十字交叉得到高低浓度质量比3∶2。','蒸发掉的是纯水不是盐水；直接将原料浓度平均会误判混合比例。',{'kind':'evap','low':'1/5','high':'2/5','mass':30,'water':6,'target':'2/5'})
add(21,'深化','重复置换与补水','浓度指溶质质量分数，忽略析出与其他损耗。100千克浓度50%的理想溶液，每次充分混匀后倒出20千克，再加20千克纯水；如此操作两次。之后还需加多少千克纯水，使浓度降为25%？',[20,24,28,32],2,'每次倒出的是当前溶质质量的20%；再用溶质质量守恒求最终总质量。','两次后溶质质量50×0.8²=32千克，总质量仍100。浓度25%要求总质量128千克，再加28千克水。','第二次倒出的盐比第一次少，不是连续减去相同溶质质量。',{'kind':'replacement','mass':100,'salt':50,'remove':20,'times':2,'target':'1/4'})
add(22,'综合','有名分组与组长','6名职工分到甲、乙两个工作组，每组3人。张、王必须在不同组，并且都不能当组长。每组从本组成员中选1名组长。共有多少种安排？',[24,36,48,72],2,'先定有名称的组，再在每组剩余2人中选组长。','张所在组有2种；再从其余4人选2人与张同组，有6种。另一组自动确定。每组有2名可选组长，乘2×2，总2×6×4=48。','甲乙组有名称，不能再除2；张王不能任组长使每组不是3种。',{'kind':'leaders','n':6,'size':3,'fixed':[0,1]})
add(23,'综合','容量取整与最低成本','43人出游，大船每条坐7人、租金50元，小船每条坐4人、租金32元，允许空座，船只数量不限。最低租金是多少元？',[306,314,328,350],1,'同时看总座位数和船的条数，尝试把费用写成这两个量的正系数组合。','设总座位S=7a+4b，船数N=a+b，则费用50a+32b=6S+8N。43人要求S≥43，每船至多7座又使N≥7，所以费用至少6×43+8×7=314元。5大2小恰43座、7条船，达到下界，故314。这个变换不用逐个枚举；常规检验可取大船a=0至7，分别补足小船，费用为352、338、356、342、328、314、332、350，结论相同。','只租人均便宜的大船要350元；平均成本只是方向，不保证离散最优。',{'kind':'boats','people':43,'seats':[7,4],'prices':[50,32]})
add(24,'综合','整除约束与方案数','用大车和小车运103吨货，大车每次运8吨，小车每次运5吨，每次装满且两种车都使用。以两种车运输次数的组合区分方案，共有多少种方案？',[1,2,3,4],2,'只看大车次数模5，再用两种车都要用确定上下界。','8a+5b=103，模5得3a≡3，所以a≡1(mod5)。b≥1使a≤12，a≥1，所以a=1、6、11，共3种（对应b=19、11、3）。这是同余缩小候选集，不是盲试12次。','两种车都用要求正整数；找到一个解后按大车次数增加5递推，别逐个试数。',{'kind':'transport','mass':103,'large':8,'small':5})
# 根据独立题面审计校准层级，不把普通比例题伪装为综合题。
for n,level in {1:'熟练',2:'深化',5:'熟练',6:'熟练',12:'深化',16:'熟练',20:'深化',24:'深化'}.items():
    Q[n-1]['level']=level
    Q[n-1]['timeLimit']={'熟练':55,'深化':75,'综合':100}[level]
output=ROOT/'原创复合24.js'
content='// AI逐题编写，非真题；由make_challenge24.py再生\nwindow.CHALLENGE_Q = '+json.dumps(Q,ensure_ascii=False,indent=2)+';\n'
if '--check' in sys.argv:
    if output.read_bytes()!=content.encode('utf-8'):raise SystemExit('生成器与24题成品不同；请重建并重新审计')
    print('24题生成器复现检查通过')
else:
    output.write_bytes(content.encode('utf-8'))
    print('Authored:',len(Q))

